public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the start and end points are valid
    if (start.length != n || end.length != n) {
        return "cannot be travelled";
    }

    // Create a visited array to keep track of visited n-tersections
    boolean[][] visited = new boolean[n][n];

    // Initialize the visited array with false
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            visited[i][j] = false;
        }
    }

    // Perform DFS from the start point
    dfs(start, end, visited, paths);

    // Check if the end point is visited
    if (visited[end[0]][end[1]]) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

private static void dfs(int[] start, int[] end, boolean[][] visited, int[][] paths) {
    // Check if the start point is visited
    if (!visited[start[0]][start[1]]) {
        // Mark the current point as visited
        visited[start[0]][start[1]] = true;

        // Check if the current point is the end point
        if (start[0] == end[0] && start[1] == end[1]) {
            return;
        }

        // Get the neighbors of the current point
        int[] neighbors = getNeighbors(start, paths);

        // Recursively call DFS for each neighbor
        for (int i = 0; i < neighbors.length; i++) {
            dfs(neighbors[i], end, visited, paths);
        }
    }
}

private static int[] getNeighbors(int[] point, int[][] paths) {
    // Initialize the neighbors array
    int[] neighbors = new int[paths.length];

    // Iterate through the paths array
    for (int i = 0; i < paths.length; i++) {
        if (paths[i][0] == point[0] && paths[i][1] == point[1]) {
            // Add the neighbor to the neighbors array
            neighbors[i] = paths[i];
        }
    }

    // Return the neighbors array
    return neighbors;
}

