public String sortString(String s) {
    if (s.length() <= 1) {
        return s;
    }

    char smallest = s.charAt(0);
    char largest = s.charAt(s.length() - 1);
    String result = "";

    int count = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c < smallest) {
            smallest = c;
        } else if (c > largest) {
            largest = c;
        }
    }

    while (count < s.length()) {
        char c = s.charAt(count++);
        if (c == smallest) {
            result += c;
        } else if (c == largest) {
            result += c;
        }
    }

    for (int i = s.length() - 1; i >= 0; i--) {
        char c = s.charAt(i);
        if (c == largest) {
            result += c;
        } else if (c == smallest) {
            result += c;
        }
    }

    return result;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    double average = (double) sum / nums.length;
    for (int i = 0; i < nums.length - 1; i++) {
        int leftSum = 0;
        for (int j = 0; j <= i; j++) {
            leftSum += nums[j];
        }
        int rightSum = sum - leftSum;
        if (Math.abs(leftSum - rightSum) / (nums.length - i - 1) == Math.abs(average)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
