    int leftBrackets = 0;
    int rightBrackets = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            leftBrackets++;
        } else if (s.charAt(i) == ')') {
            rightBrackets++;
        }
