public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int currLength = 1;
                int left = j - 1;
                int right = j + 1;
                int up = i - 1;
                int down = i + 1;
                while (left >= 0 && mat[i][left] == 1) {
                    currLength++;
                    left--;
                }
                while (right < n && mat[i][right] == 1) {
                    currLength++;
                    right++;
                }
                while (up >= 0 && mat[up][j] == 1) {
                    currLength++;
                    up--;
                }
                while (down < m && mat[down][j] == 1) {
                    currLength++;
                    down++;
                }
                maxLength = Math.max(maxLength, currLength);
            }
        }
    }
    return maxLength;
}

